import type { ModelTurn } from "./llm-client.js";
import type { ConversationMessage } from "./session-manager.js";
import { isToolCall, type ToolCall } from "./tool-calling.js";

export type AgentLoopOptions = {
  callModel: (inputItems: unknown[]) => Promise<ModelTurn>;
  executeTool: (call: ToolCall) => Promise<string>;
  maximumTurns?: number;
};

export type AgentRunResult = {
  answer: string;
  newMessages: ConversationMessage[];
};

export function conversationMessagesToInputItems(
  messages: ConversationMessage[],
): unknown[] {
  return messages.map((message) => {
    switch (message.type) {
      case "user":
        return {
          role: "user",
          content: [{ type: "input_text", text: message.text }],
        };
      case "assistant":
        return {
          role: "assistant",
          content: [{ type: "output_text", text: message.text }],
        };
      case "tool_call":
        return {
          type: "function_call",
          call_id: message.call_id,
          name: message.name,
          arguments: message.arguments,
        };
      case "tool_result":
        return {
          type: "function_call_output",
          call_id: message.call_id,
          output: message.output,
        };
    }
  });
}

export async function runAgent(
  messages: ConversationMessage[],
  options: AgentLoopOptions,
): Promise<AgentRunResult> {
  const inputItems: unknown[] = conversationMessagesToInputItems(messages);
  const newMessages: ConversationMessage[] = [];
  const maximumTurns = options.maximumTurns ?? 20;

  for (let turn = 0; turn < maximumTurns; turn++) {
    const response = await options.callModel(inputItems);

    // Preserve everything the model produced.
    inputItems.push(...response.output);

    const toolCalls = response.output.filter(isToolCall);

    // No tool calls means the model has finished.
    if (toolCalls.length === 0) {
      newMessages.push({ type: "assistant", text: response.outputText });
      return {
        answer: response.outputText,
        newMessages,
      };
    }

    for (const call of toolCalls) {
      let displayedArguments: unknown = call.arguments;
      try {
        displayedArguments = JSON.parse(call.arguments) as unknown;
      } catch {
        // Keep the original string so malformed arguments are still visible.
      }

      console.error("\n[model -> tool_call]");
      console.error(JSON.stringify({
        call_id: call.call_id,
        name: call.name,
        arguments: displayedArguments,
      }, null, 2));

      newMessages.push({
        type: "tool_call",
        call_id: call.call_id,
        name: call.name,
        arguments: call.arguments,
      });

      const result = await options.executeTool(call);

      console.error("[tool -> function_call_output]");
      console.error(JSON.stringify({
        call_id: call.call_id,
        name: call.name,
        outputCharacters: result.length,
      }, null, 2));

      newMessages.push({
        type: "tool_result",
        call_id: call.call_id,
        name: call.name,
        output: result,
      });

      inputItems.push({
        type: "function_call_output",
        call_id: call.call_id,
        output: result,
      });
    }

    // The loop now sends the expanded input back to the model.
  }

  throw new Error(
    `Agent exceeded the maximum of ${maximumTurns} model turns`,
  );
}
import * as fs from "node:fs/promises";
import * as path from "node:path";

export type ToolDefinition = {
  type: "function";
  name: string;
  description: string;
  parameters: Record<string, unknown>;
  strict: boolean;
};

export type ToolCall = {
  type: "function_call";
  call_id: string;
  name: string;
  arguments: string;
};

export function isToolCall(item: { type: string; [key: string]: unknown }): item is ToolCall {
  return (
    item.type === "function_call" &&
    typeof item.call_id === "string" &&
    typeof item.name === "string" &&
    typeof item.arguments === "string"
  );
}

async function readFileTool(args: unknown, workspaceDirectory: string): Promise<string> {
  if (
    !args ||
    typeof args !== "object" ||
    typeof (args as { path?: unknown }).path !== "string"
  ) {
    throw new Error("read_file requires a string path");
  }

  const requestedPath = (args as { path: string }).path;

  const workspaceRoot = await fs.realpath(workspaceDirectory);
  const targetPath = await fs.realpath(
    path.resolve(workspaceRoot, requestedPath),
  );

  const relativePath = path.relative(workspaceRoot, targetPath);
  const outsideWorkspace =
    relativePath === ".." ||
    relativePath.startsWith(`..${path.sep}`) ||
    path.isAbsolute(relativePath);

  if (outsideWorkspace) {
    throw new Error("Cannot read files outside the workspace");
  }

  return fs.readFile(targetPath, "utf8");
}

export function createToolCallingSystem(workspaceDirectory = process.cwd()) {
  const tools: ToolDefinition[] = [
    {
      type: "function",
      name: "read_file",
      description: "Read the UTF-8 text contents of a file in the current workspace.",
      parameters: {
        type: "object",
        properties: {
          path: {
            type: "string",
            description: "File path relative to the workspace root",
          },
        },
        required: ["path"],
        additionalProperties: false,
      },
      strict: true,
    },
  ];

  async function executeTool(call: ToolCall): Promise<string> {
    try {
      const args: unknown = JSON.parse(call.arguments);

      switch (call.name) {
        case "read_file":
          return await readFileTool(args, workspaceDirectory);

        default:
          throw new Error(`Unknown tool: ${call.name}`);
      }
    } catch (error) {
      return JSON.stringify({
        error: error instanceof Error ? error.message : String(error),
      });
    }
  }

  return { tools, executeTool };
}
import * as fs from "node:fs/promises";
import * as path from "node:path";

export type UserMessage = {
  type: "user";
  text: string;
};

export type AssistantMessage = {
  type: "assistant";
  text: string;
};

export type ToolCallMessage = {
  type: "tool_call";
  call_id: string;
  name: string;
  arguments: string;
};

export type ToolResultMessage = {
  type: "tool_result";
  call_id: string;
  name: string;
  output: string;
};

export type ConversationMessage =
  | UserMessage
  | AssistantMessage
  | ToolCallMessage
  | ToolResultMessage;

export function createSessionManager(
  conversationsDirectory = path.join(process.cwd(), "conversations"),
) {
  function sessionPath(sessionId: number): string {
    return path.join(conversationsDirectory, `${sessionId}.json`);
  }

  async function createNewSession(): Promise<{ id: number; messages: ConversationMessage[] }> {
    await fs.mkdir(conversationsDirectory, { recursive: true });
    const files = await fs.readdir(conversationsDirectory);
    const existingIds = files
      .map((file) => /^([1-9]\d*)\.json$/.exec(file)?.[1])
      .filter((id): id is string => id !== undefined)
      .map(Number);
    const id = existingIds.length === 0 ? 1 : Math.max(...existingIds) + 1;
    const messages: ConversationMessage[] = [];

    await saveSession(id, messages);
    return { id, messages };
  }

  async function loadSession(sessionIdText: string): Promise<{ id: number; messages: ConversationMessage[] }> {
    if (!/^[1-9]\d*$/.test(sessionIdText)) {
      throw new Error("세션 ID는 1 이상의 정수여야 합니다.");
    }

    const id = Number(sessionIdText);
    let parsed: unknown;
    try {
      parsed = JSON.parse(await fs.readFile(sessionPath(id), "utf8"));
    } catch (error) {
      const code = (error as NodeJS.ErrnoException).code;
      if (code === "ENOENT") throw new Error(`${id}번 세션을 찾을 수 없습니다.`);
      throw error;
    }

    if (!Array.isArray(parsed) || !parsed.every(isConversationMessage)) {
      throw new Error(`${id}.json의 대화 형식이 올바르지 않습니다.`);
    }
    return { id, messages: parsed };
  }

  function isConversationMessage(value: unknown): value is ConversationMessage {
    if (!value || typeof value !== "object") return false;
    const item = value as Record<string, unknown>;

    if (item.type === "user" || item.type === "assistant") {
      return typeof item.text === "string";
    }

    if (item.type === "tool_call") {
      return (
        typeof item.call_id === "string" &&
        typeof item.name === "string" &&
        typeof item.arguments === "string"
      );
    }

    if (item.type === "tool_result") {
      return (
        typeof item.call_id === "string" &&
        typeof item.name === "string" &&
        typeof item.output === "string"
      );
    }

    return false;
  }

  async function saveSession(sessionId: number, messages: ConversationMessage[]): Promise<void> {
    await fs.mkdir(conversationsDirectory, { recursive: true });
    await fs.writeFile(sessionPath(sessionId), `${JSON.stringify(messages, null, 2)}\n`, "utf8");
  }

  return { createNewSession, loadSession, saveSession };
}
import type { ToolCall, ToolDefinition } from "./tool-calling.js";

export type ModelOutputItem = ToolCall | {
  type: string;
  [key: string]: unknown;
};

export type ModelTurn = {
  output: ModelOutputItem[];
  outputText: string;
};

export type LlmClientOptions = {
  baseUrl: string;
  gatewayToken: string;
  model: string;
  instructions?: string;
};

export function createLlmClient(options: LlmClientOptions, tools: ToolDefinition[]) {
  const baseUrl = options.baseUrl.replace(/\/+$/, "");

  return async function callModel(inputItems: unknown[]): Promise<ModelTurn> {
    if (!baseUrl || !options.gatewayToken || !options.model) {
      throw new Error(
        "OPENAI_BASE_URL, GATEWAY_TOKEN, OPENAI_MODEL을 먼저 설정하세요.",
      );
    }

    const response = await fetch(
      `${baseUrl}/responses`,
      {
        method: "POST",
        headers: {
          Authorization: `Bearer ${options.gatewayToken}`,
          "Content-Type": "application/json",
          Accept: "text/event-stream",
        },
        body: JSON.stringify({
          model: options.model,
          store: false,
          stream: true,
          instructions: options.instructions ?? "You are a helpful assistant.",
          tools,
          input: inputItems,
        }),
      },
    );

    if (!response.ok) {
      throw new Error(
        `Request failed (${response.status}): ${await response.text()}`,
      );
    }

    const reader = response.body?.getReader();
    if (!reader) {
      throw new Error("Response body is not readable");
    }

    const decoder = new TextDecoder();

    let buffer = "";
    let outputText = "";
    let completedOutput: ModelOutputItem[] | undefined;
    const completedItems: ModelOutputItem[] = [];
    const observedEventTypes = new Set<string>();

    function handleSseLine(line: string): void {
      if (!line.startsWith("data:")) return;

      const data = line.slice(5).trimStart();
      if (!data || data === "[DONE]") return;

      let event: Record<string, any>;
      try {
        event = JSON.parse(data) as Record<string, any>;
      } catch (error) {
        throw new Error(
          `Failed to parse an SSE event: ${error instanceof Error ? error.message : String(error)}`,
        );
      }

      if (typeof event.type === "string") {
        observedEventTypes.add(event.type);
      }

      if (
        event.type === "error" ||
        event.type === "response.failed" ||
        event.type === "response.incomplete"
      ) {
        const message =
          typeof event.error?.message === "string"
            ? event.error.message
            : typeof event.message === "string"
              ? event.message
              : JSON.stringify(event);
        throw new Error(`Model response failed: ${message}`);
      }

      if (
        event.type === "response.output_text.delta" &&
        typeof event.delta === "string"
      ) {
        outputText += event.delta;
      }

      if (
        event.type === "response.output_item.done" &&
        event.item
      ) {
        completedItems.push(event.item as ModelOutputItem);
      }

      if (
        event.type === "response.completed" &&
        Array.isArray(event.response?.output)
      ) {
        completedOutput = event.response.output as ModelOutputItem[];
      }
    }

    while (true) {
      const { done, value } = await reader.read();
      if (done) break;

      buffer += decoder.decode(value, { stream: true });

      const lines = buffer.split("\n");
      buffer = lines.pop() ?? "";

      for (const line of lines) {
        handleSseLine(line);
      }
    }

    buffer += decoder.decode();
    for (const line of buffer.split("\n")) {
      handleSseLine(line);
    }

    const output =
      completedItems.length > 0
        ? completedItems
        : completedOutput ?? [];

    if (output.length === 0 && outputText.length === 0) {
      const observed = [...observedEventTypes].join(", ") || "none";
      throw new Error(
        `Model returned no recognized output. Observed SSE events: ${observed}`,
      );
    }

    return {
      output,
      outputText,
    };
  };
}

