 * 한 요청을 실행합니다. sessionId를 생략하면 새 세션을 만듭니다.
 * 반환된 sessionId를 다음 호출에 전달하면 같은 대화를 이어갑니다.
 *
 * const result = await jeffy({
 *   input: "package.json을 읽고 설명해줘",
 *   baseUrl: "https://your-worker.example.workers.dev/v1",
 *   gatewayToken,
 *   model: "your-api-model",
 *   instructions: "한국어로 간결하게 답하세요.",
 * });
 */
export async function jeffy(options: JeffyOptions): Promise<JeffyResult> {
  const workspaceRoot = path.resolve(options.workspaceRoot ?? process.cwd());
  const sessionManager = createSessionManager(
    options.conversationsDirectory ?? path.join(workspaceRoot, "conversations"),
  );
  const toolCalling = createToolCallingSystem(workspaceRoot);
  const callModel = createLlmClient(options, toolCalling.tools);

  const session = options.sessionId === undefined
    ? await sessionManager.createNewSession()
    : await sessionManager.loadSession(String(options.sessionId));

  session.messages.push({ type: "user", text: options.input });
  await sessionManager.saveSession(session.id, session.messages);

  const { answer, newMessages } = await runAgent(session.messages, {
    callModel,
    executeTool: toolCalling.executeTool,
    maximumTurns: options.maximumTurns,
  });

  session.messages.push(...newMessages);
  await sessionManager.saveSession(session.id, session.messages);

  return { sessionId: session.id, answer };
}
# Project Context

This is a learning project for building a minimal LLM agent harness inspired by pi. The goal is to understand the smallest system that can handle:

`user request -> reasoning -> tool call/execution -> reasoning -> ... -> final response`

The scope includes the agent loop, context and conversation management, tool definition and execution, and memory.

## Assistant Role

- Guide the user while assuming they are studying how agent systems work.
- Explain necessary concepts and design choices before implementation.
- Prefer the smallest working design and separate essential mechanisms from optional complexity.
- Describe control flow and component boundaries with concise pseudocode, then implement requested code.
- Keep implementation details brief unless the user asks to inspect them.
